// Verified against MC 26.2 (Mojang mappings). This file COMPILES against
// ~/.gradle/caches/fabric-loom/26.2/{minecraft-common,minecraft-client-only}.jar (javac 25, exit 0).
// Read-only: it never calls BlockItem.place / Level.setBlock, so it cannot desync the client.
import net.minecraft.core.BlockPos;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;

public final class PlacementPredictor {
    public record Prediction(BlockPos pos, boolean likelySucceeds) {}

    /** `level` must be player.level() -- the public ctor ignores any other Level (5-arg ctor is protected). */
    public static Prediction predict(Level level, Player player, InteractionHand hand,
                                     ItemStack stack, BlockHitResult hit) {
        BlockPlaceContext ctx = new BlockPlaceContext(player, hand, stack, hit);
        BlockPos pos = ctx.getClickedPos();          // hit pos if replaceable, else hitPos.relative(face)

        if (!(stack.getItem() instanceof BlockItem blockItem)) return new Prediction(pos, false);
        if (!ctx.canPlace()) return new Prediction(pos, false);                     // target pos replaceable?
        if (!level.isInWorldBounds(pos)) return new Prediction(pos, false);
        if (!level.getWorldBorder().isWithinBounds(pos)) return new Prediction(pos, false);
        if (!player.mayUseItemAt(pos, hit.getDirection(), stack)) return new Prediction(pos, false);
        if (!player.isWithinBlockInteractionRange(pos, 1.0)) return new Prediction(pos, false);

        // public stand-in for the protected BlockItem.getPlacementState
        BlockState state = blockItem.getBlock().getStateForPlacement(ctx);
        if (state == null) return new Prediction(pos, false);

        // verbatim body of the protected BlockItem.canPlace(ctx, state), with mustSurvive() assumed true
        boolean ok = state.canSurvive(level, pos)
                && level.isUnobstructed(state, pos, CollisionContext.placementContext(player));
        return new Prediction(pos, ok);
    }

    public static boolean replacesClickedBlock(Player player, InteractionHand hand,
                                              ItemStack stack, BlockHitResult hit) {
        return new BlockPlaceContext(player, hand, stack, hit).replacingClickedOnBlock();
    }
}
// Known blind spots (no client-visible API): ServerLevel spawn protection (Level.mayInteract is
// hardcoded true client-side), server-side reach/anticheat, and BlockItem.mustSurvive()==false
// (scaffolding) which is protected and so assumed true above.
